package it.farmacidicasa;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.os.*;import org.json.*;import java.time.*;
public class ReminderReceiver extends BroadcastReceiver {
 public static void schedule(Context c){LocalDateTime next=LocalDate.now().atTime(9,0);if(!next.isAfter(LocalDateTime.now()))next=next.plusDays(1);long millis=next.atZone(ZoneId.systemDefault()).toInstant().toEpochMilli();PendingIntent p=PendingIntent.getBroadcast(c,1,new Intent(c,ReminderReceiver.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);AlarmManager a=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);a.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,millis,p);}
 @Override public void onReceive(Context c,Intent i){try{notifyNow(c,false);}finally{schedule(c);}}
 public static void notifyNow(Context c,boolean test){NotificationManager manager=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);manager.createNotificationChannel(new NotificationChannel("reminders","Scadenze e scorte",NotificationManager.IMPORTANCE_DEFAULT));if(Build.VERSION.SDK_INT>=33&&c.checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED){if(test)android.widget.Toast.makeText(c,"Abilita le notifiche nelle impostazioni Android",1).show();return;}int soon=0,low=0;try(Store store=new Store(c)){for(JSONObject b:store.boxes("")){if(Store.soon(b))soon++;if(Store.low(b))low++;}}if(soon==0&&low==0&&!test){manager.cancel(101);return;}PendingIntent open=PendingIntent.getActivity(c,0,new Intent(c,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);String text=test?"Notifiche attive. "+soon+" confezioni in scadenza, "+low+" sotto scorta.":soon+" confezioni in scadenza / oltre il limite, "+low+" sotto scorta minima.";manager.notify(101,new Notification.Builder(c,"reminders").setSmallIcon(it.farmacidicasa.R.drawable.ic_home).setContentTitle("Farmaci di casa").setContentText(text).setStyle(new Notification.BigTextStyle().bigText(text)).setContentIntent(open).setAutoCancel(true).build());}
}
